files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  font-family: system-ui, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 #0f0f1a;
}
h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
}
.stats {
  display: flex;
  gap: 24px;
  margin-bottom: 20px;
  color: var(--muted);
}
.stats strong { color: var(--text); }
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}
input[type="text"] {
  flex: 1;
  padding: 10px 12px;
  font-size: 1rem;
  background: var(--bg);
  border: 2px solid var(--muted);
  color: var(--text);
  border-radius: 0;
  outline: none;
}
input[type="text"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}
button {
  padding: 10px 16px;
  font-size: 1rem;
  font-weight: bold;
  text-transform: uppercase;
  background: var(--accent);
  color: var(--text);
  border: 2px solid var(--accent);
  border-radius: 0;
  cursor: pointer;
  transition: transform 0.05s, background 0.15s;
}
button:hover { background: #ff6b81; }
button:active { transform: translate(2px, 2px); }
button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}
ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  background: var(--bg);
  border: 2px solid var(--muted);
}
li input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
}
li span {
  flex: 1;
  word-break: break-word;
}
li.done span {
  text-decoration: line-through;
  color: var(--muted);
}
li button {
  padding: 4px 10px;
  font-size: 0.85rem;
  background: transparent;
  border-color: var(--muted);
  color: var(--muted);
}
li button:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--text);
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  .input-row { flex-direction: column; }
  button { width: 100%; }
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

let nextId = 1;
let total = 0;
let remaining = 0;

function updateCounts() {
  totalEl.textContent = total;
  remainingEl.textContent = remaining;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;

  const id = nextId++;
  total++;
  remaining++;
  updateCounts();

  const li = document.createElement('li');
  li.dataset.id = id;
  li.dataset.done = 'false';

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = 'todo-check-' + id;
  checkbox.setAttribute('aria-label', 'Mark task ' + id + ' as done');

  const span = document.createElement('span');
  span.id = 'todo-text-' + id;
  span.textContent = text;

  const delBtn = document.createElement('button');
  delBtn.id = 'todo-delete-' + id;
  delBtn.textContent = 'Delete';
  delBtn.setAttribute('aria-label', 'Delete task ' + id);

  checkbox.addEventListener('change', () => {
    if (checkbox.checked) {
      remaining--;
      li.classList.add('done');
      li.dataset.done = 'true';
    } else {
      remaining++;
      li.classList.remove('done');
      li.dataset.done = 'false';
    }
    updateCounts();
  });

  delBtn.addEventListener('click', () => {
    if (li.dataset.done === 'false') {
      remaining--;
    }
    total--;
    updateCounts();
    li.remove();
  });

  li.append(checkbox, span, delBtn);
  list.appendChild(li);
  input.value = '';
  input.focus();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
